<?php $register=($_GET['mode']??'')==='register';$otp=$register||($_GET['method']??'')==='otp'; ?>
<section class="auth-card" aria-labelledby="auth-title">
<a class="auth-brand" href="<?= $this->h($this->url('/')) ?>"><img src="/assets/morshed-logo-288.webp" width="96" height="96" alt="مرشد"><span>مرشد</span></a>
<h1 id="auth-title"><?= $register?'ساخت حساب مرشد':'خوش آمدی' ?></h1><p class="muted auth-intro">برای گفت‌وگو با مرشد، وارد حسابت شو.</p>
<nav class="auth-tabs" aria-label="ورود یا ثبت نام"><a <?= !$register?'aria-current="page"':'' ?> href="<?= $this->h($this->url('/login')) ?>">ورود</a><a <?= $register?'aria-current="page"':'' ?> href="<?= $this->h($this->url('/login?mode=register')) ?>">ثبت نام</a></nav>
<?php if($otp): ?><?= $this->start('/auth/otp/request') ?><input type="hidden" name="purpose" value="login"><?= $this->field('phone','شماره همراه','tel') ?><button class="primary full"><?= $register?'دریافت کد و ساخت حساب':'دریافت کد ورود' ?></button></form><p class="muted small">ثبت نام پس از تأیید شماره همراه با کد پیامکی انجام می‌شود.</p><?php if(!$register): ?><a class="textlink" href="<?= $this->h($this->url('/login')) ?>">ورود با رمز عبور</a><?php endif; ?>
<?php else: ?><?= $this->start('/auth/password') ?><?= $this->field('login','نام کاربری یا شماره همراه','text') ?><?= $this->field('password','رمز عبور','password') ?><button class="primary full">وارد شوید</button></form><div class="auth-links"><a href="<?= $this->h($this->url('/login?method=otp')) ?>">ورود با کد یک‌بارمصرف</a><a href="<?= $this->h($this->url('/password/recover')) ?>">فراموشی رمز عبور</a></div><?php endif; ?>
<div class="auth-divider"><span>یا ادامه با</span></div><div class="auth-providers">
<?php foreach(['eitaa'=>'ایتا','google'=>'گوگل'] as $provider=>$label): $available=($this->config[$provider]['enabled']??false)&&($this->config[$provider]['live_verified']??false); ?><?= $this->start('/auth/'.$provider.'/start') ?><input type="hidden" name="purpose" value="login"><?php if($provider==='eitaa'): ?><input type="hidden" name="init_data" data-eitaa-input><p class="small hidden" data-eitaa-status role="status"></p><?php endif; ?><button class="secondary full" <?= $available?'':'disabled' ?>>ورود با <?= $label ?></button></form><?php endforeach; ?></div>
<p class="muted small">روش‌های غیرفعال هنوز راه‌اندازی نشده‌اند. ورود با ایتا پس از تأیید شماره به همان حساب شماره‌دار متصل می‌شود.</p><a class="auth-back" href="<?= $this->h($this->url('/')) ?>">بازگشت به ویترین و مشاهدهٔ تجربه‌ها</a></section>
